(function(){
  try {
    function setInputValue(selector, value) {
      let el = document.querySelector(selector);
      if (!el) {
        const all = document.querySelectorAll('*');
        for (const node of all) {
          if (node.shadowRoot) {
            el = node.shadowRoot.querySelector(selector);
            if (el) break;
          }
        }
      }
      if (el) {
        el.value = value;
        el.dispatchEvent(new Event('input', { bubbles: true }));
        el.dispatchEvent(new Event('change', { bubbles: true }));
        return true;
      }
      return false;
    }

    const r1 = setInputValue('#field-name', 'Jane Smith');
    const r2 = setInputValue('#field-address', '123 Test Lane');
    const r3 = setInputValue('#field-city', 'Anytown');
    const r4 = setInputValue('#field-zip', '00000');
    const r5 = setInputValue('#field-card', '4111111111111111');
    const r6 = setInputValue('#field-expiry', '12/28');
    const r7 = setInputValue('#field-cvv', '123');

    let btn = document.querySelector('#place-order-btn');
    if (!btn) {
      const all = document.querySelectorAll('*');
      for (const node of all) {
        if (node.shadowRoot) {
          btn = node.shadowRoot.querySelector('#place-order-btn');
          if (btn) break;
        }
      }
    }
    if (btn) {
      btn.click();
      return 'Success: form filled and order placed (' + [r1,r2,r3,r4,r5,r6,r7].join(',') + ')';
    }
    return 'Error: place order button not found';
  } catch(e) {
    return 'Error: ' + e.message;
  }
})()
